diff --git a/expirable/expirable_lru.go b/expirable/expirable_lru.go
index 85687d4..7d35ca4 100644
--- a/expirable/expirable_lru.go
+++ b/expirable/expirable_lru.go
@@ -211,6 +211,24 @@ func (c *LRU[K, V]) Peek(key K) (value V, ok bool) {
 	return
 }

+// PeekWithExpiry returns the key value and the time the entry expires
+// (or undefined if not found), without updating the "recently used"-ness
+// of the key. A missing key, or one that has already expired, returns the
+// zero value, the zero time and false.
+func (c *LRU[K, V]) PeekWithExpiry(key K) (value V, expiresAt time.Time, ok bool) {
+	c.mu.Lock()
+	defer c.mu.Unlock()
+	var ent *internal.Entry[K, V]
+	if ent, ok = c.items[key]; ok {
+		// Expired item check
+		if !c.cleanupStopped && time.Now().After(ent.ExpiresAt) {
+			return value, expiresAt, false
+		}
+		return ent.Value, ent.ExpiresAt, true
+	}
+	return
+}
+
 // Remove removes the provided key from the cache, returning if the
 // key was contained. If it was, onEvict is invoked for the removed
 // entry outside the cache's internal lock.

